"use strict";const requestForm=document.getElementById("request-form"),fieldMap={titre:document.getElementById("titre"),competence:document.getElementById("competence"),urgence:document.getElementById("urgence"),description:document.getElementById("description"),mentor:document.getElementById("mentor")};function setFieldError(e,t){const r=document.getElementById(`error-${e.id}`);e.setAttribute("aria-invalid","true"),r&&(r.textContent=t)}function clearFieldError(e){const t=document.getElementById(`error-${e.id}`);e.setAttribute("aria-invalid","false"),t&&(t.textContent="")}function validateForm(){let e=!0;return["titre","competence","urgence","description"].forEach(t=>{const r=fieldMap[t];if(!r)return;r.value.trim()?clearFieldError(r):(setFieldError(r,"Champ requis"),e=!1)}),e}function prefillMentor(){const e=new URLSearchParams(window.location.search).get("mentor");e&&fieldMap.mentor&&(fieldMap.mentor.value=e)}requestForm?.addEventListener("submit",e=>{e.preventDefault(),validateForm()?(showToast?.("Demande envoyee avec succes.","success"),setTimeout(()=>{window.location.href="mes_demandes.php"},900)):showToast?.("Merci de verifier les champs requis.","info")}),prefillMentor();